+            stmt.setBytes(1, new byte[] { 5 });
+            stmt.executeUpdate();
+            stmt.setBytes(1, new byte[] { 5, 0 });
+            stmt.executeUpdate();
+            stmt.setBytes(1, new byte[] { 5, 1 });
+            stmt.executeUpdate();
+            conn.commit();
+
+            stmt = conn.prepareStatement(sql2);
+            stmt.setBytes(1, new byte[] { 5 });
+            ResultSet rs = stmt.executeQuery();
+
+            assertTrue(rs.next());
