+      assertThat(result.get("e"), equalTo(5));
+      assertThat(result.get("f"), equalTo(6));
+    }
+    {
+      String query = "MAP_MERGE( [ { 'a' : '1', 'b' : '2' }, { 'c' : '3', 'd' : '4' }, { 'e' : '5', 'f' : '6' } ] )";

